css:
.ss-docs{border:1px solid var(--line);background:var(--card);height:100%}
.ss-docs__h{display:flex;flex-wrap:wrap;align-items:baseline;justify-content:space-between;gap:10px;padding:22px 24px;border-bottom:1px solid var(--line)}
.ss-docs__t{font-family:var(--font-heading);font-weight:800;font-size:19px;margin:0}
.ss-docs__m{font:700 10px/1 var(--font-body);letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}
.ss-docs__l{list-style:none;margin:0;padding:0}
.ss-docs__l li+li{border-top:1px solid var(--line)}
.ss-docs__l a{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:14px 24px;font-size:14px;font-weight:600;color:var(--ink);text-decoration:none}
.ss-docs__l a:hover{background:var(--paper);color:var(--accent)}
.ss-docs__k{font:700 10px/1 var(--font-body);letter-spacing:.08em;color:var(--accent);white-space:nowrap}
.ss-docs--grid{border:0;background:none;height:auto}
.ss-docs--grid .ss-docs__h{padding:0 0 18px;border-bottom:0}
.ss-docs--grid .ss-docs__l{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,380px),1fr));gap:16px}
.ss-docs--grid .ss-docs__l li{border:1px solid var(--line);background:var(--card)}
.ss-docs--grid .ss-docs__l a{padding:20px 22px}
.ss-docs--dark .ss-docs__t{color:#EDEDED}
.ss-docs--dark .ss-docs__m{color:#A0A0A0}
.ss-docs--dark.ss-docs--grid .ss-docs__l li{background:transparent;border-color:rgba(255,255,255,.22)}
.ss-docs--dark .ss-docs__l a{color:#EDEDED}
.ss-docs--dark .ss-docs__l a:hover{background:rgba(255,255,255,.06);color:#fff}
